  need(len(anchor)>=3,f'ASCII anchor too short: {anchor}'); return any((m.start()==0 or not text[m.start()-1].isalnum()) and (m.end()==len(text) or not text[m.end()].isalnum()) for m in re.finditer(re.escape(anchor),text))
